function homeView() {
  const latest = state.sessions.at(-1); const hasResume = Boolean(state.activeAssessment);
  return shell(`<section class="hero"><div class="hero__copy"><p class="hero__eyebrow">給 16–18 歲學生的防詐決策訓練</p><h1>90 秒，練習在關鍵時刻<br><span>做對下一步。</span></h1><p class="hero__text">不是替你猜真假。SignalSafe 讓你練習先停下、找出關鍵訊號，再改走官方查證。</p><div class="hero__actions"><button class="button button--primary button--large" data-action="start-quick">${icon("bolt",21)}開始 90 秒快練</button><button class="button button--secondary button--large" data-route="emergency">${icon("siren",21)}我現在遇到可疑狀況</button></div>${hasResume ? `<button class="resume-link" data-action="resume-assessment">繼續未完成的完整測驗 ${icon("arrow",18)}</button>` : ""}</div><div class="hero__visual" aria-hidden="true"><div class="phone-demo"><div class="phone-demo__top"><span></span><span></span></div><div class="message-bubble message-bubble--incoming">可以幫我投票嗎？<br>只差 3 票，現在登入就好</div><div class="risk-chip">外部登入＋限時壓力</div><div class="decision-card"><span>${icon("shield",22)}</span><div><strong>先不要點連結</strong><small>用原聯絡方式向本人確認</small></div></div></div></div></section><section class="principles" aria-label="SignalSafe 三步驟"><article><span>01</span><div><h2>先停下</h2><p>停止點擊、登入、付款或提供資料。</p></div></article><article><span>02</span><div><h2>找訊號</h2><p>看話術、來源、要求行為與金流。</p></div></article><article><span>03</span><div><h2>去查證</h2><p>回原 App、官網或公開聯絡方式。</p></div></article></section><section class="mode-grid"><article class="mode-card mode-card--primary"><div class="mode-card__icon">${icon("bolt",28)}</div><div><p class="mode-card__meta">日常模式</p><h2>90 秒快練</h2><p>3 個短情境，只回答最安全行動與一個關鍵訊號。</p></div><button class="text-button" data-action="start-quick">開始快練 ${icon("arrow",17)}</button></article><article class="mode-card"><div class="mode-card__icon">${icon("brain",28)}</div><div><p class="mode-card__meta">課堂／研究模式</p><h2>完整能力測驗</h2><p>前測、訓練、後測，共 24 題。完整記錄判斷、證據與自信。</p></div><button class="text-button" data-route="assessment-intro">查看流程 ${icon("arrow",17)}</button></article><article class="mode-card"><div class="mode-card__icon">${icon("chart",28)}</div><div><p class="mode-card__meta">本機紀錄</p><h2>我的學習盲點</h2><p>${latest ? "查看最近一次的行動、校準與誤判指標。" : "完成訓練後，這裡會顯示你的判斷盲點。"}</p></div><button class="text-button" data-route="dashboard">查看紀錄 ${icon("arrow",17)}</button></article></section><section class="privacy-strip"><span class="privacy-strip__icon">${icon("lock",23)}</span><div><strong>不登入、不上傳、不蒐集姓名或學校。</strong><p>${state.storageMode==="memory"?"目前為暫時記憶模式；重新整理或關閉頁面可能遺失資料。你仍可匯出備份。":"所有紀錄保存在這台裝置，你可以隨時匯出或清除。"}</p></div><button class="button button--ghost" data-route="data">管理資料</button></section>`);
}
function startQuestionTimer(){questionStartedAt=performance.now();interruptedDuration=0;hiddenStartedAt=null;}
function elapsedMs(){const now=performance.now();const activeHidden=hiddenStartedAt?now-hiddenStartedAt:0;return Math.max(0,now-questionStartedAt-interruptedDuration-activeHidden);}
function createResponse(question,selections,phase){const signalResult=signalScores(selections.signalIds,question.correctSignalIds);return {id:crypto.randomUUID(),questionId:question.id,phase,selectedActionId:selections.actionId,correctActionIds:question.correctActionIds,isActionCorrect:question.correctActionIds.includes(selections.actionId),selectedJudgment:selections.judgment??null,correctJudgment:question.correctJudgment,isJudgmentCorrect:selections.judgment?selections.judgment===question.correctJudgment:false,selectedSignalIds:selections.signalIds,correctSignalIds:question.correctSignalIds,signalPrecision:signalResult.precision,signalRecall:signalResult.recall,signalF1:signalResult.f1,confidence:selections.confidence??null,responseTimeMs:Math.round(elapsedMs()),wasInterrupted:interruptedDuration>0||Boolean(hiddenStartedAt),submittedAt:new Date().toISOString()};}
